"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[85041],{28453:(e,n,t)=>{t.d(n,{R:()=>r,x:()=>i});var a=t(96540);const s={},o=a.createContext(s);function r(e){const n=a.useContext(o);return a.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function i(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),a.createElement(o.Provider,{value:n},e.children)}},44867:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>i,default:()=>m,frontMatter:()=>r,metadata:()=>a,toc:()=>h});const a=JSON.parse('{"id":"tangfen/chinaneedmen","title":"","description":"Just had some Moutai, feeling a bit merry, so let me talk about what real men are. What China needs right now are real men. What\'s the standard for a real man? A true man\'s breath is the breath of the universe; the universe is as if contained in his belly. Time is like the pulse of his life; the world is like pebbles beneath his feet. A true man holds heaven and earth in his sleeves; history is but a glance before his eyes.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/chinaneedmen.md","sourceDirName":"tangfen","slug":"/tangfen/chinaneedmen","permalink":"/en/tangfen/chinaneedmen","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"chinaneedmen","title":"","hide_table_of_contents":true},"sidebar":"tangfenSidebar","previous":{"title":"\u7f20\u5973\u58eb\uff0c\u793c\u5c1a\u5f80\u6765\uff0c\u6211\u8981\u6311\u6218\u4f60\uff01","permalink":"/en/tangfen/challengechan"},"next":{"title":"ZT:\u5168\u5317\u4eac\u6709\u53f2\u4ee5\u6765\u5e73\u5747\u667a\u5546\u6700\u9ad8\u7684\u4e00\u6b21\u996d\u5c40 \uff08\u6ce8\uff1a\u7f20\u8f6c\u8d34\uff09","permalink":"/en/tangfen/mostintelligentdinner"}}');var s=t(74848),o=t(28453);const r={id:"chinaneedmen",title:"",hide_table_of_contents:!0},i="What China Needs Is Real Men",l={},h=[];function d(e){const n={h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"what-china-needs-is-real-men",children:"What China Needs Is Real Men"})}),"\n",(0,s.jsx)(n.p,{children:"Just had some Moutai, feeling a bit merry, so let me talk about what real men are. What China needs right now are real men. What's the standard for a real man? A true man's breath is the breath of the universe; the universe is as if contained in his belly. Time is like the pulse of his life; the world is like pebbles beneath his feet. A true man holds heaven and earth in his sleeves; history is but a glance before his eyes."}),"\n",(0,s.jsx)(n.p,{children:"What China needs is real men. So-called laws and patterns are nothing but excuses for some people's moaning. The formation of patterns cannot be separated from the people who form them. The patterns of history are composed by the people in history -- without people in history, where would the patterns of history come from? The so-called Six Classics are merely footnotes to us real men. Standing tall between heaven and earth is still the servitude of the constrained!"}),"\n",(0,s.jsx)(n.p,{children:"Some might want to spout nonsense about idealism. Without people, where would idealism come from? People come first; real men come first. Whether a world is excellent or not -- one basic standard is whether the men are real men. A world that turns men into women is certainly not a brave new world.\nThose who like to play it safe will never have a brave new world. The pioneering of the world has always been paved with the blood of real men. The rise of China needs precisely this blood of real men."}),"\n",(0,s.jsx)(n.p,{children:"Some may talk about the reckless courage of common men. But what do real men have to do with common men! Common men are like manipulated machines, while real men have clear minds and sharp eyes -- the world is like a little peach in the palm of their hands. What's truly lacking now are real men. Now everyone is just objects suppressed by so-called laws and rules, not knowing that the world was originally beneath the feet of real men. Being crushed by the world is only because you're kneeling!"}),"\n",(0,s.jsx)(n.p,{children:"Real men never kneel. Real men die standing! The world is pioneered beneath the feet of real men. Without real men, this world would lose all its color! The rise of China truly needs real men. Beneath the feet of real men, the world needs to be named. The world is named by real men. A world without real men is no world at all!"})]})}function m(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}}}]);